import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

@SpringBootTest
class ContactViewTest extends SpringBrowserlessTest {

    @Test
    void headingAndAboutLink() {
        ContactView view = navigate(ContactView.class);
        assertEquals("Contact", $(H1.class).first().getText());
        assertEquals("About", $(RouterLink.class).first().getText());
    }

    @Test
    void sendIsEnabledOnEmptyForm() {
        navigate(ContactView.class);
        Button send = $(Button.class).id("send-not-set").withText("Send").single();
    }

    @Test
    void emptyFormSendIsEnabled() {
        navigate(ContactView.class);
        Button send = findSendButton();
        assertTrue(test(send).isUsable());
    }

    @Test
    void blankFormValidationFails() {
        navigate(ContactView.class);
        Button send = findSendButton();
        test(send).click();

        TextField name = $(TextField.class).withLabel("Name").single();
        EmailField email = $(EmailField.class).withLabel("Email").single();
        TextArea message = $(TextArea.class).withLabel("Message").single();

        assertTrue(name.isInvalid());
        assertEquals("Name is required", name.getErrorMessage());
        assertTrue(email.isInvalid());
        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
        assertTrue(message.isInvalid());
        assertEquals("Message is required", message.getErrorMessage());

        assertEquals(0, $(Grid.class).first().getElement().getChildCount() >= 0 ? countRows() : -1);
    }

    private int countRows() {
        return $(Grid.class).first() == null ? 0 : new com.vaadin.flow.component.grid.GridTester<>($(Grid.class).first()).size();
    }

    @Test
    void invalidEmailIsRejected() {
        navigate(ContactView.class);
        TextField name = $(TextField.class).withLabel("Name").single();
        EmailField email = $(EmailField.class).withLabel("Email").single();
        TextArea message = $(TextArea.class).withLabel("Message").single();

        test(name).setValue("Ann");
        test(email).setValue("not-an-email");
        test(message).setValue("Hello there");

