+package com.example.views;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.dialog.DialogTester;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.notification.NotificationTester;
+import com.vaadin.flow.component.routerlink.RouterLinkTester;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void headingAndAboutLink() {
+        ContactView view = navigate(ContactView.class);
+        assertEquals("Contact", $(H1.class).first().getText());
+        assertEquals("About", $(RouterLink.class).first().getText());
+    }
+
+    @Test
+    void emptyFormSendIsEnabled() {
+        navigate(ContactView.class);
+        Button send = findSendButton();
+        assertTrue(test(send).isUsable());
+    }
+
+    @Test
+    void blankFormValidationFails() {
+        navigate(ContactView.class);
+        int before = new com.vaadin.flow.component.grid.GridTester<>($(Grid.class).first()).size();
+        Button send = findSendButton();
+        test(send).click();
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        assertEquals(before,
+                new com.vaadin.flow.component.grid.GridTester<>($(Grid.class).first()).size());
+    }
+
+    @Test
+    void invalidEmailIsRejected() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+
+        test(name).setValue("Ann");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello there");
+
+        Button send = findSendButton();
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+    }
+
+    @Test
+    void successfulSendClearsFormAndDisablesSendUntilEdit() {
+        navigate(ContactView.class);
+        int before = new com.vaadin.flow.component.grid.GridTester<>($(Grid.class).first()).size();
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = findSendButton();
+
+        test(name).setValue("Ann");
+        test(email).setValue("ann@example.com");
+        test(message).setValue("Hello there");
+
+        test(send).click();
+
+        NotificationTester<Notification> notificationTester = test($(Notification.class).first());
+        assertTrue(notificationTester.getText().contains("Message sent"));
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", message.getValue());
+
+        assertFalse(test(send).isUsable());
+
+        test(name).setValue("Bob");
+        assertTrue(test(send).isUsable());
+
+        Grid<?> grid = $(Grid.class).first();
+        assertEquals(before + 1, new com.vaadin.flow.component.grid.GridTester<>(grid).size());
+    }
+
+    @Test
+    void enterKeySendsMessage() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+
+        test(name).setValue("Ann");
+        test(message).setValue("Hi");
+        $(TextField.class).withLabel("Phone").single();
+        test($(TextField.class).withLabel("Phone").single()).setValue("12345");
+
+        fireShortcut(Key.ENTER);
+
+        assertTrue($(Notification.class).first() != null);
+    }
+
+    @Test
+    void leavingWithUnsavedInputShowsDialog() {
+        ContactView view = navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        test(name).setValue("Ann");
+
+        RouterLinkTester<RouterLink> link = test($(RouterLink.class).first());
+        link.navigate();
+
+        Dialog dialog = $(Dialog.class).first();
+        org.junit.jupiter.api.Assertions.assertNotNull(dialog);
+
+        Button keepEditing = $(Button.class, dialog).withText("Keep editing").single();
+        test(keepEditing).click();
+
+        assertEquals("Ann", name.getValue());
+        org.junit.jupiter.api.Assertions.assertTrue(getCurrentView() instanceof ContactView);
+    }
+
+    @Test
+    void leavingWithUnsavedInputCanDiscard() {
+        navigate(ContactView.class);
+        TextField name = $(TextField.class).withLabel("Name").single();
+        test(name).setValue("Ann");
+
+        RouterLinkTester<RouterLink> link = test($(RouterLink.class).first());
+        link.navigate();
+
+        Dialog dialog = $(Dialog.class).first();
+        Button discard = $(Button.class, dialog).withText("Discard").single();
+        test(discard).click();
+
+        org.junit.jupiter.api.Assertions.assertTrue(getCurrentView() instanceof AboutView);
+    }
+
+    @Test
+    void leavingWithEmptyFormDoesNotShowDialog() {
+        navigate(ContactView.class);
+
+        RouterLinkTester<RouterLink> link = test($(RouterLink.class).first());
+        link.navigate();
+
+        org.junit.jupiter.api.Assertions.assertTrue(getCurrentView() instanceof AboutView);
+    }
+
+    private Button findSendButton() {
+        return $(Button.class).withText("Send").single();
+    }
+}
